window.OSHA_QUESTIONS_SET3 = [
  { id: "fk-01", category: "forklift", topic: "Norma", q: "Los camiones industriales motorizados (montacargas) en industria general están cubiertos por:", choices: ["29 CFR 1910.178", "solo 1926.500", "solo 1910.147", "solo el MUTCD"], a: 0, why: "1910.178 es la norma de PIT. La construcción también usa 1926.602 para equipo de manejo de materiales." },
  { id: "fk-02", category: "forklift", topic: "Certificación", q: "La certificación de operador de montacargas la emite:", choices: ["OSHA en una tarjeta de plástico del DOL", "El empleador después de la capacitación y la evaluación", "El DMV estatal en todos los estados", "Solo el fabricante del camión"], a: 1, why: "No hay “licencia OSHA de montacargas” federal. El empleador certifica a los operadores en el equipo que usarán." },
  { id: "fk-03", category: "forklift", topic: "Partes de la capacitación", q: "La capacitación de PIT debe incluir:", choices: ["Instrucción formal, capacitación práctica y una evaluación del desempeño en el lugar de trabajo", "Solo un video", "Solo leer la placa de datos", "Un examen escrito sin conducir"], a: 0, why: "1910.178(l)(2): las tres. Los temas incluyen estabilidad, tablas de carga y peligros específicos del lugar de trabajo." },
  { id: "fk-04", category: "forklift", topic: "Intervalo de evaluación", q: "El desempeño del operador debe evaluarse al menos cada:", choices: ["6 meses", "3 años", "10 años", "Nunca después de la certificación inicial"], a: 1, why: "1910.178(l)(4)(iii): al menos una vez cada 3 años, y antes después de un incidente u operación insegura." },
  { id: "fk-05", category: "forklift", topic: "Reciclaje", q: "Se exige capacitación de reciclaje cuando:", choices: ["El operador participa en un accidente, un casi accidente, se le observa operar de forma insegura, o cambian las condiciones", "El operador pide un sombrero nuevo", "Solo si cambia de empresa en otro estado", "Nunca"], a: 0, why: "También se exige si se le asigna un tipo distinto de camión." },
  { id: "fk-06", category: "forklift", topic: "Placa de datos", q: "La placa de datos del montacargas muestra:", choices: ["Estaciones de radio", "Capacidad, centro de carga e información de tipo/peso del camión", "El nombre del operador", "Solo el color de la pintura"], a: 1, why: "Nunca exceda la capacidad. Los aditamentos cambian la capacidad: la placa debe reflejarlos." },
  { id: "fk-07", category: "forklift", topic: "Triángulo de estabilidad", q: "Un montacargas contrapesado de sentado es estable cuando el centro de gravedad combinado permanece:", choices: ["Fuera del eje trasero", "Dentro del triángulo de estabilidad formado por las ruedas delanteras y el pivote del eje de dirección", "Por encima del resguardo superior", "En las puntas de las horquillas"], a: 1, why: "Elevar una carga, inclinar hacia adelante, girar y las cargas descentradas mueven el CG. Así ocurren las volcaduras." },
  { id: "fk-08", category: "forklift", topic: "Volcadura", q: "Si un montacargas de conductor sentado se vuelca, el operador debe:", choices: ["Saltar cuesta abajo", "Quedarse sentado, agarrarse e inclinarse lejos de la caída, con el cinturón puesto", "Pararse sobre la batería", "Agarrar el resguardo superior y saltar"], a: 1, why: "Saltar es cómo los operadores quedan aplastados por el resguardo superior. Cinturón puesto." },
  { id: "fk-09", category: "forklift", topic: "Circulación", q: "Al circular con una carga en una rampa:", choices: ["Carga cuesta arriba (upgrade) cuando va cargado, en general", "Carga cuesta abajo siempre", "Girar de lado en la rampa", "Elevar la carga para ver"], a: 0, why: "Cargado: horquillas cuesta arriba. Vacío: horquillas cuesta abajo. Mantenga la carga cuesta arriba para que no se deslice." },
  { id: "fk-10", category: "forklift", topic: "Rampa vacío", q: "Al circular sin carga en una pendiente, las horquillas en general apuntan:", choices: ["Cuesta arriba", "Cuesta abajo", "De lado", "Lo más alto posible"], a: 1, why: "Los camiones vacíos son más pesados atrás. Horquillas cuesta abajo mantiene el CG más estable en pendientes." },
  { id: "fk-11", category: "forklift", topic: "Velocidad", q: "La velocidad del montacargas debe ser:", choices: ["La misma que el tráfico de carretera", "Lo bastante lenta para detenerse con seguridad según las condiciones, las cargas y los peatones", "Tan rápida como el camión pueda ir en un pasillo", "Control crucero a 20 mph en interiores"], a: 1, why: "1910.178(n)(8): velocidades que permitan detenerse. Los pisos mojados y las esquinas ciegas necesitan más lentitud." },
  { id: "fk-12", category: "forklift", topic: "Claxon", q: "Toque el claxon:", choices: ["En esquinas ciegas, al acercarse a peatones y cuando lo exijan las reglas del lugar de trabajo", "De forma continua", "Nunca, asusta a la gente", "Solo al aire libre"], a: 0, why: "1910.178(n)(4): reduzca la velocidad y toque el claxon en cruces de pasillos y otros lugares donde la visión esté obstruida." },
  { id: "fk-13", category: "forklift", topic: "Estacionamiento", q: "Al dejar un montacargas desatendido, usted debe:", choices: ["Dejarlo encendido en marcha", "Bajar por completo las horquillas, neutralizar los controles, apagar la energía y poner el freno; calce si está en una pendiente", "Dejar las horquillas a la altura de los ojos como advertencia", "Estacionar en un carril peatonal"], a: 1, why: "1910.178(m)(5): desatendido significa que el operador está a más de 25 pies o fuera de la vista. Si sigue a la vista dentro de 25 pies, al menos baje horquillas, neutralice y ponga el freno." },
  { id: "fk-14", category: "forklift", topic: "Definición de desatendido", q: "Un PIT se considera desatendido cuando el operador está:", choices: ["Sentado en él hablando", "A más de 25 pies o siempre que el camión no esté a la vista", "Usando el cinturón", "En un descanso en la cabina"], a: 1, why: "1910.178(m)(5)(ii)–(iii)." },
  { id: "fk-15", category: "forklift", topic: "Personas en las horquillas", q: "Levantar personas en horquillas o tarimas está:", choices: ["Permitido si se agarran", "Prohibido salvo que se use una plataforma de trabajo debidamente diseñada y se cumplan las condiciones del fabricante/OSHA", "Siempre exigido para surtido de pedidos", "Bien bajo 4 pies"], a: 1, why: "1910.178(m)(3): no hay pasajeros salvo lo permitido. Las plataformas aéreas de construcción tienen sus propias reglas (1926.453)." },
  { id: "fk-16", category: "forklift", topic: "Aditamentos", q: "Los desplazadores laterales, las pinzas y los pescantes:", choices: ["Nunca cambian la capacidad", "Pueden reducir la capacidad y deben aprobarse; la placa de datos debe coincidir con la configuración", "Le permiten exceder la placa en un 20%", "Son decorativos"], a: 1, why: "El momento de la carga cambia. Obtenga la clasificación del distribuidor/fabricante." },
  { id: "fk-17", category: "forklift", topic: "Carga de baterías", q: "Las áreas de carga de baterías necesitan:", choices: ["Ninguna precaución especial", "Ventilación, no fumar, lavaojos/equipo de emergencia según se exija, y EPP para el ácido", "Llamas abiertas para secar las baterías", "Cargar en una escalera de madera"], a: 1, why: "1910.178(g): el gas hidrógeno es explosivo. Mantenga lejos las fuentes de ignición. Neutralice los derrames de ácido de forma adecuada." },
  { id: "fk-18", category: "forklift", topic: "Cambio de propano", q: "Al cambiar un tanque de LP:", choices: ["Fume para buscar fugas", "Cierre la válvula, use EPP según se exija y revise las conexiones; hágalo en un área bien ventilada lejos de la ignición", "Cambie tanques en interiores junto a un calentador", "Ventile el combustible a un desagüe"], a: 1, why: "El LP es más pesado que el aire. Las fugas se acumulan abajo. No fume." },
  { id: "fk-19", category: "forklift", topic: "Inspección diaria", q: "La inspección previa al uso suele incluir:", choices: ["Llantas, horquillas, mástil, cadenas, fugas, resguardo superior, claxon, luces y frenos", "Solo el portavasos", "Descascare de pintura", "El volumen de la radio"], a: 0, why: "1910.178(q)(7): examine al menos a diario. Retire de servicio si es inseguro." },
  { id: "fk-20", category: "forklift", topic: "Retirar de servicio", q: "Si los frenos fallan la inspección, el operador debe:", choices: ["Conducir despacio al taller a través del patio", "No operar el camión hasta que se repare", "Usar el freno de estacionamiento como frenos de servicio", "Hacer que un vigía lo empuje"], a: 1, why: "1910.178(p)(1): todo camión industrial motorizado que no esté en condición segura de operación se retirará de servicio." },
  { id: "fk-21", category: "forklift", topic: "Respaldo de carga", q: "Una extensión de respaldo de carga se usa para:", choices: ["Aumentar la potencia del motor", "Evitar que la carga caiga hacia el operador cuando está apilada alta en las horquillas", "Reemplazar el resguardo superior", "Remolcar tráileres"], a: 1, why: "1910.178(e)(2): respaldo de altura adecuada cuando el tipo de carga lo requiere." },
  { id: "fk-22", category: "forklift", topic: "Resguardo superior", q: "El resguardo superior protege contra:", choices: ["Objetos que caen (paquetes/objetos pequeños); no es garantía contra el colapso completo de un rack", "Electrocución", "CO", "Ruido"], a: 0, why: "1910.178(e)(1): resguardo superior. No detendrá una carga de 2,000 lb que cae de un rack alto." },
  { id: "fk-23", category: "forklift", topic: "Muelle", q: "Antes de entrar a un tráiler, el operador debe:", choices: ["Asumir que el tráiler no se puede mover", "Verificar que el tráiler esté calzado/con gato según se exija, que la placa de muelle esté segura y que el piso sostendrá el camión", "Entrar a toda velocidad", "Elevar la carga hasta el techo"], a: 1, why: "El deslizamiento del tráiler y el colapso del tren de aterrizaje matan operadores. Importan los calzos, las sujeciones y la inspección del piso del tráiler." },
  { id: "fk-24", category: "forklift", topic: "Pasillo estrecho", q: "Los montacargas de alcance de pie tienen distintos:", choices: ["Características de estabilidad y necesidades de capacitación que los camiones contrapesados de sentado", "Normas de OSHA que los prohíben", "Reglas que saltan la evaluación", "Necesidad de placas de datos"], a: 0, why: "1910.178(l): la capacitación debe ser específica del tipo de camión. Alcance, surtidor de pedidos y gato de tarimas son distintos." },
  { id: "fk-25", category: "forklift", topic: "Derecho del peatón", q: "Los peatones en un almacén deben:", choices: ["Compartir pasillos sin marcar a velocidad de carrera", "Usar pasarelas designadas, hacer contacto visual y nunca caminar bajo una carga elevada", "Asumir que el operador los ve", "Viajar en las horquillas al comedor"], a: 1, why: "Separe a las personas y los PIT cuando pueda. La alta visibilidad ayuda pero no reemplaza la distancia." },
  { id: "fk-26", category: "forklift", topic: "Monóxido de carbono", q: "Los montacargas IC (combustión interna) en áreas mal ventiladas pueden causar:", choices: ["Intoxicación por CO", "Solo calor extra que es saludable", "Mejor calidad del aire", "Ningún peligro si se usa propano"], a: 0, why: "El propano, la gasolina y el diésel producen CO. Mantenga las afinaciones y ventile. Considere camiones eléctricos en interiores." },
  { id: "fk-27", category: "forklift", topic: "Placa faltante", q: "Si la placa de capacidad falta o no se puede leer:", choices: ["Adivine 5,000 lb", "No opere hasta que se reemplace con la información correcta", "Use la placa del último camión", "Pida a un compañero que estime"], a: 1, why: "1910.178(a)(6): las placas de identificación y los marcados deben estar en su lugar y mantenerse." },
  { id: "fk-28", category: "forklift", topic: "Edad", q: "La norma de PIT de OSHA exige que los operadores tengan:", choices: ["Al menos 18 años", "16 con una nota de los padres", "21 para todos los almacenes", "Cualquier edad si están supervisados"], a: 0, why: "Las órdenes de ocupaciones peligrosas y la práctica de 1910.178: 18 es el mínimo general para montacargas." },
  { id: "fk-29", category: "forklift", topic: "Cumplimiento del cinturón", q: "El empleador debe:", choices: ["Exigir el uso de los sistemas de sujeción del operador provistos en el camión", "Quitar los cinturones para que los operadores puedan saltar", "Ignorar los cinturones si la producción está atrasada", "Solo instalar cinturones en camiones nuevos y nunca usarlos"], a: 0, why: "OSHA hace cumplir el uso del cinturón bajo la capacitación 1910.178(l) y la Cláusula de deber general / instrucciones del fabricante." },
  { id: "fk-30", category: "forklift", topic: "Modificaciones", q: "Las modificaciones que afectan la capacidad o la operación segura:", choices: ["Están bien si las suelda un amigo", "Deben tener aprobación previa por escrito del fabricante", "Nunca necesitan documentación", "Las exige OSHA anualmente"], a: 1, why: "1910.178(a)(4): aprobación del fabricante. Luego actualice la placa." },
  { id: "hz-01", category: "hazwoper", topic: "Norma", q: "HAZWOPER es:", choices: ["29 CFR 1910.120 (y 1926.65 para construcción)", "La norma de protección contra caídas", "Un tipo de casco", "Solo una regla de EPA sin superposición con OSHA"], a: 0, why: "Hazardous Waste Operations and Emergency Response cubre limpieza, instalaciones TSD y respuesta de emergencia a liberaciones." },
  { id: "hz-02", category: "hazwoper", topic: "40 horas", q: "Los trabajadores generales de un sitio de limpieza de desechos peligrosos que están expuestos a peligros en general necesitan:", choices: ["4 horas de concientización", "40 horas de instrucción fuera del sitio más un mínimo de 3 días de experiencia real de campo bajo un supervisor", "Solo OSHA 10", "Solo una tarjeta de montacargas"], a: 1, why: "1910.120(e)(3)(i): 40 horas + 3 días de experiencia de campo supervisada para trabajadores generales del sitio." },
  { id: "hz-03", category: "hazwoper", topic: "24 horas", q: "Los trabajadores en el sitio solo de forma ocasional para una tarea limitada específica, con exposición improbable por encima de los PEL, pueden calificar para:", choices: ["Ninguna capacitación", "24 horas de capacitación más un día de experiencia de campo (con límites en la norma)", "80 horas", "Un doctorado en química"], a: 1, why: "1910.120(e)(3)(ii)–(iii): la categoría de 24 horas es más estrecha que la de trabajadores generales de 40 horas." },
  { id: "hz-04", category: "hazwoper", topic: "Reciclaje de 8 horas", q: "El reciclaje anual de HAZWOPER es en general:", choices: ["8 horas", "40 horas cada año", "Opcional", "15 minutos"], a: 0, why: "1910.120(e)(8): 8 horas de capacitación de reciclaje anual para quienes la necesitan." },
  { id: "hz-05", category: "hazwoper", topic: "Primer respondiente de concientización", q: "El personal de primer respondiente a nivel de concientización:", choices: ["Se detiene, observa y llama: no intenta contener la liberación más allá de iniciar el sistema de respuesta de emergencia", "Se pone Nivel A y entra a la zona caliente", "Parchea carros tanque", "Actúa siempre como comandante del incidente"], a: 0, why: "1910.120(q)(6)(i): concientización = reconocer, notificar y mantenerse atrás." },
  { id: "hz-06", category: "hazwoper", topic: "Nivel de operaciones", q: "El personal de primer respondiente a nivel de operaciones:", choices: ["Responde con fines defensivos: contiene desde una distancia segura, impide que se extienda, sin intentar detener la liberación en la fuente", "Realiza control ofensivo de la fuente en todos los casos", "No necesita capacitación", "Solo escribe informes"], a: 0, why: "1910.120(q)(6)(ii): al menos 8 horas o competencia equivalente. Defensivo, no ofensivo." },
  { id: "hz-07", category: "hazwoper", topic: "Técnico", q: "Los técnicos de materiales peligrosos:", choices: ["Se acercan al punto de liberación para tapar, parchear o detenerla (ofensivo)", "Solo llaman al 911", "Son lo mismo que concientización", "Nunca usan EPP"], a: 0, why: "1910.120(q)(6)(iii): 24 horas más competencia. Trabajan en la zona caliente con sistema de compañeros." },
  { id: "hz-08", category: "hazwoper", topic: "IC", q: "El Comandante del incidente en una emergencia HAZMAT debe tener:", choices: ["Al menos 24 horas de capacitación equivalentes al nivel de operaciones más competencia adicional en el ICS y los peligros", "Solo un radio", "Solo concientización", "Ninguna capacitación si es gerente"], a: 0, why: "1910.120(q)(6)(v): se especifica la capacitación del IC. Se exige la estructura ICS." },
  { id: "hz-09", category: "hazwoper", topic: "Sistema de compañeros", q: "En la zona caliente durante la respuesta de emergencia, las operaciones suelen usar:", choices: ["Trabajadores solos para reducir la exposición", "El sistema de compañeros", "Ninguna comunicación", "Solo celulares sin radios"], a: 1, why: "1910.120(q)(3): sistema de compañeros y personal de respaldo. Nadie entra solo." },
  { id: "hz-10", category: "hazwoper", topic: "ERP", q: "Un Plan de respuesta de emergencia para emergencias químicas debe incluir:", choices: ["Planificación previa, funciones del personal, comunicación, EPP y evacuación, entre otros elementos", "Solo un número de teléfono en la pared", "Un mapa de la cafetería", "Nada escrito"], a: 0, why: "1910.120(q)(2) lista los elementos requeridos. Si no va a responder, debe tener un plan de acción de emergencia y evacuar." },
  { id: "hz-11", category: "hazwoper", topic: "Opción de evacuar", q: "Los empleadores que evacuarán a todos los empleados y no responderán a una liberación:", choices: ["Aun así necesitan un plan de acción de emergencia (1910.38) y llamar a respondientes externos", "Necesitan un equipo completo de técnicos en cada turno", "No necesitan ningún plan", "Solo necesitan SDS"], a: 0, why: "1910.120(q)(1): puede elegir no responder, pero debe evacuar y tener un EAP." },
  { id: "hz-12", category: "hazwoper", topic: "Control del sitio", q: "Las zonas típicas de trabajo HAZWOPER son:", choices: ["Caliente (exclusión), tibia (reducción de contaminación) y fría (apoyo)", "Solo un estacionamiento", "Rojo y azul solo para eléctrico", "Dentro y fuera del condado"], a: 0, why: "1910.120(d) y (q): las zonas de control limitan la dispersión de la contaminación." },
  { id: "hz-13", category: "hazwoper", topic: "Descontaminación", q: "La descontaminación es:", choices: ["Opcional si usted es cuidadoso", "Obligatoria para evitar dispersar contaminantes; la línea se arma antes de que alguien entre en estado contaminado", "Solo una ducha en casa al día siguiente", "Solo para herramientas, nunca para personas"], a: 1, why: "1910.120(k): procedimientos escritos de descontaminación. Descontaminación gruesa en la CRZ." },
  { id: "hz-14", category: "hazwoper", topic: "Médico", q: "La vigilancia médica de HAZWOPER se exige en general para:", choices: ["Empleados en ciertos trabajos de limpieza, que usan respiradores 30+ días/año, o lesionados por exposición, entre otros umbrales", "Solo personal de oficina", "Nadie", "Solo contratistas de otros estados"], a: 0, why: "1910.120(f): exámenes médicos antes de la asignación, anuales (o bienales con aprobación del médico) y al terminar en muchos casos." },
  { id: "hz-15", category: "hazwoper", topic: "Monitoreo", q: "El monitoreo del aire en un sitio de desechos peligrosos se usa para:", choices: ["Determinar EPP, zonas de trabajo y si existen condiciones IDLH o inflamables", "Entretener a la cuadrilla", "Reemplazar el plan de seguridad del sitio", "Medir solo el ruido"], a: 0, why: "1910.120(h): monitoreo inicial y periódico. Conozca las limitaciones de su medidor (factores de corrección, O2 para LEL)." },
  { id: "hz-16", category: "hazwoper", topic: "IDLH HAZWOPER", q: "Si la atmósfera de un sitio de desechos peligrosos es IDLH, en general necesita:", choices: ["N95", "SCBA de presión positiva o equivalente, y una persona de rescate de reserva", "Cubrebocas quirúrgicos", "Ninguna protección respiratoria si aguanta la respiración"], a: 1, why: "1910.120(g)(3)(iii) y las reglas IDLH de 1910.134." },
  { id: "hz-17", category: "hazwoper", topic: "Plan de seguridad del sitio", q: "Un programa escrito de seguridad y salud para operaciones de limpieza incluye:", choices: ["Una estructura organizacional, un plan de trabajo y un plan de seguridad y salud específico del sitio", "Solo facturas", "Una lista de empaque", "Instrucciones verbales una vez"], a: 0, why: "1910.120(b): programa integral. El SSHP aborda los peligros de ese sitio." },
  { id: "hz-18", category: "hazwoper", topic: "Tambores", q: "Abrir o mover tambores sin etiqueta en un sitio de desechos:", choices: ["Es trabajo casual", "Requiere procedimientos para manejar tambores sensibles al golpe, explosivos o desconocidos; se colocan y se inspeccionan con cuidado", "Debe hacerse rodándolos cuesta abajo", "No necesita EPP"], a: 1, why: "1910.120(j): manejo de tambores y recipientes. Importan la apertura remota, la puesta a tierra y la colocación." },
  { id: "hz-19", category: "hazwoper", topic: "TSD", q: "Los trabajadores en instalaciones TSD de RCRA en general necesitan:", choices: ["24 horas de capacitación más competencia, con reciclaje de 8 horas (o un programa equivalente)", "Ninguna capacitación si tienen OSHA 10", "40 horas si nunca salen", "Solo una tarjeta de montacargas"], a: 0, why: "1910.120(p)(7): la capacitación TSD es de 24 horas inicialmente en muchos casos, no siempre el curso de limpieza de 40 horas." },
  { id: "hz-20", category: "hazwoper", topic: "Niveles de EPP", q: "El conjunto de protección química EPA/OSHA Nivel A es:", choices: ["Ropa de calle", "Traje hermético al vapor con SCBA (la mayor protección de piel y respiratoria)", "Solo delantal y guantes", "Solo casco y chaleco"], a: 1, why: "El Nivel B es SCBA con traje no hermético al vapor. El Nivel C es APR con ropa similar. El Nivel D es uniforme básico de trabajo. Seleccione según el peligro, no el alfabeto." },
  { id: "hz-21", category: "hazwoper", topic: "Nivel D", q: "La protección Nivel D es:", choices: ["Adecuada para IDLH", "Ropa de trabajo básica cuando se sabe que la atmósfera es segura y no hay peligro para la piel", "Un traje totalmente encapsulante", "Siempre exigida en sitios Superfund"], a: 1, why: "No “suba” ni “baje” de nivel a la ligera. El monitoreo respalda el nivel." },
  { id: "hz-22", category: "hazwoper", topic: "Calor en EPP", q: "Trabajar con ropa de protección química aumenta:", choices: ["El riesgo de estrés por calor; pueden necesitarse descanso, hidratación y monitoreo fisiológico", "Solo el estrés por frío", "La agudeza auditiva", "Siempre el oxígeno dentro del traje"], a: 0, why: "Los programas médicos y de calor de HAZWOPER se superponen. Los trajes totalmente encapsulantes son hornos." },
  { id: "hz-23", category: "hazwoper", topic: "Compatibilidad", q: "Los materiales de guantes y trajes deben:", choices: ["Elegirse por compatibilidad química y tiempo de penetración, no solo por el color", "Ser siempre nitrilo para todo químico", "Ser látex para solventes siempre", "Ser algodón para ácidos"], a: 0, why: "Un químico que pasa el nitrilo en minutos puede estar bien en butilo o Viton. Revise las tablas." },
  { id: "hz-24", category: "hazwoper", topic: "Después de la emergencia", q: "Después de una emergencia, la limpieza de sustancias peligrosas derramadas puede caer bajo:", choices: ["Las disposiciones de limpieza de HAZWOPER si es una operación de desechos peligrosos según se define", "Ninguna norma de OSHA", "Solo códigos de incendio", "Solo la norma de montacargas"], a: 0, why: "Una vez que termina la emergencia, la limpieza restante puede ser 1910.120(b)–(o) en lugar de (q)." },
  { id: "hz-25", category: "hazwoper", topic: "DOT ERG", q: "La Guía de respuesta de emergencia del DOT se usa para:", choices: ["Encontrar distancias iniciales de aislamiento y peligros generales a partir de placards/ID en un incidente de transporte", "Reemplazar siempre las SDS en el lugar de trabajo", "Certificar técnicos HAZMAT", "Fijar PEL"], a: 0, why: "El ERG es para primeros respondientes a distancia. No sustituye un IAP completo ni las SDS en una instalación fija." },
  { id: "bb-01", category: "bloodborne", topic: "Norma", q: "La Norma de patógenos transmitidos por la sangre es:", choices: ["1910.1030", "1926.501", "1910.147", "1904.39"], a: 0, why: "Cubre la exposición ocupacional a sangre y otros materiales potencialmente infecciosos (OPIM)." },
  { id: "bb-02", category: "bloodborne", topic: "OPIM", q: "OPIM incluye:", choices: ["Solo sudor", "Fluidos corporales humanos como semen, secreciones vaginales, líquido cefalorraquídeo y cualquier fluido corporal visiblemente contaminado con sangre, entre otros listados", "Solo sangre animal en todos los casos", "Agua potable"], a: 1, why: "1910.1030(b): definiciones. El sudor, las lágrimas y la saliva no son OPIM salvo que estén visiblemente ensangrentados (la saliva en dental es OPIM)." },
  { id: "bb-03", category: "bloodborne", topic: "ECP", q: "El empleador debe tener un escrito:", choices: ["Plan de control de exposición, revisado al menos anualmente", "Solo una lista de botiquín", "Registro de simulacros de incendio", "Mapa de rutas de montacargas"], a: 0, why: "1910.1030(c): el ECP incluye la determinación de exposición, los métodos de cumplimiento y los procedimientos para evaluar incidentes." },
  { id: "bb-04", category: "bloodborne", topic: "Universales", q: "Las precauciones universales (estándar) significan:", choices: ["Tratar toda sangre y OPIM como infecciosos", "Tratar como infecciosos solo a los pacientes conocidos positivos a VIH", "Los guantes son opcionales", "Lavarse una vez a la semana"], a: 0, why: "No se puede saber quién es infeccioso. Use barreras cada vez." },
  { id: "bb-05", category: "bloodborne", topic: "Ingeniería", q: "Ejemplos de controles de ingeniería para BBP incluyen:", choices: ["Recipientes para punzocortantes, agujas que se recubren solas y sistemas sin aguja", "Memorandos", "Pedir a la gente que no sangre", "Poner música"], a: 0, why: "1910.1030(d)(2): primero controles de ingeniería y de práctica de trabajo. El empleador debe evaluar dispositivos más seguros anualmente." },
  { id: "bb-06", category: "bloodborne", topic: "Recipiente de punzocortantes", q: "Los punzocortantes contaminados deben desecharse en:", choices: ["Una taza de café", "Recipientes cerrables, resistentes a perforación, a prueba de fugas, rotulados o con código de color", "La basura regular si se reencapuchan", "Una bolsa de papel"], a: 1, why: "No reencapuche con técnica de dos manos. Use un recubrimiento de una mano o un dispositivo mecánico si se exige reencapuchar." },
  { id: "bb-07", category: "bloodborne", topic: "Vacuna VHB", q: "La vacunación contra hepatitis B debe:", choices: ["Ofrecerse gratis después de que el trabajador pague las primeras dos dosis", "Ponerse a disposición sin costo después de la capacitación y dentro de 10 días hábiles de la asignación a funciones con exposición ocupacional, salvo que ya sea inmune o la vacuna esté contraindicada", "Ser opcional que el empleador la mencione", "Exigirse que la pague solo el seguro del trabajador"], a: 1, why: "1910.1030(f)(2). La declinación debe ser por escrito. El trabajador igual puede recibir la vacuna después." },
  { id: "bb-08", category: "bloodborne", topic: "Después de la exposición", q: "Después de un incidente de exposición, el empleador debe:", choices: ["Proporcionar una evaluación médica confidencial y seguimiento sin costo, incluida la prueba de la fuente si se obtiene el consentimiento", "Despedir al trabajador", "Esperar 6 meses para ver", "Solo lavar el área con solvente"], a: 0, why: "1910.1030(f)(3): primeros auxilios inmediatos, reporte, evaluación, profilaxis según recomiende el Servicio de Salud Pública de EE. UU." },
  { id: "bb-09", category: "bloodborne", topic: "Etiquetas", q: "Las etiquetas de riesgo biológico son:", choices: ["Naranja fluorescente o naranja-rojo con el símbolo de riesgo biológico", "Azules y blancas", "Verdes", "Opcionales en las cajas de punzocortantes"], a: 0, why: "1910.1030(g)(1): bolsas o etiquetas rojas. La ropa sucia y los desechos regulados necesitan identificación." },
  { id: "bb-10", category: "bloodborne", topic: "Capacitación BBP", q: "La capacitación de BBP se exige:", choices: ["Al asignarse y al menos anualmente", "Una vez por carrera", "Solo para médicos", "Nunca si tiene OSHA 30"], a: 0, why: "1910.1030(g)(2): preguntas y respuestas interactivas con un instructor conocedor." },
  { id: "bb-11", category: "bloodborne", topic: "Primeros auxilios en construcción", q: "Los proveedores de primeros auxilios en construcción que pueden anticipar de forma razonable exposición a sangre:", choices: ["Pueden caer bajo BBP (o un programa comparable) aunque 1910.1030 sea una norma de industria general: OSHA la aplica por política a la construcción cuando hay exposición ocupacional", "Nunca están cubiertos", "Solo necesitan un casco", "Deben reencapuchar agujas en el aire"], a: 0, why: "OSHA ha declarado que 1910.1030 puede aplicar a la construcción donde hay exposición ocupacional. Muchos GC incluyen a los de primeros auxilios en un programa BBP." },
  { id: "bb-12", category: "bloodborne", topic: "Lavado de manos", q: "Después de quitarse los guantes:", choices: ["Lávese las manos con jabón y agua, o use un limpiador antiséptico y luego lávese tan pronto como sea factible si no había lavabo", "Límpiese en los pantalones", "Reutilice los mismos guantes toda la semana", "Enjuague con gasolina"], a: 0, why: "1910.1030(d)(2)(v)–(vi): instalaciones para lavarse las manos. Las toallitas antisépticas son una medida temporal." },
  { id: "bb-13", category: "bloodborne", topic: "EPP BBP", q: "El EPP para BBP se proporciona:", choices: ["Sin costo y no debe permitir que la sangre/OPIM pase a la ropa o la piel en uso normal", "Por el trabajador desde casa", "Solo si el paciente se ve enfermo", "Como moda opcional"], a: 0, why: "Guantes, batas, cubrebocas, protección ocular según lo exija la tarea. Alternativas hipoalergénicas si se necesitan." },
  { id: "bb-14", category: "bloodborne", topic: "VIH VHB VHC", q: "Los tres virus transmitidos por la sangre de mayor preocupación ocupacional suelen ser:", choices: ["VIH, hepatitis B y hepatitis C", "Solo influenza, sarampión y paperas", "Solo tétanos", "Solo COVID"], a: 0, why: "El VHB tiene vacuna. El VHC y el VIH no (para el VHC, el tratamiento ha mejorado pero la prevención sigue importando). El tétanos no es un virus transmitido por la sangre en este sentido." },
  { id: "bb-15", category: "bloodborne", topic: "Desecho regulado", q: "El desecho regulado incluye:", choices: ["Sangre/OPIM líquida o semilíquida, artículos contaminados que liberarían si se comprimen, y punzocortantes contaminados", "Papel de oficina", "Botellas de agua vacías", "Guantes limpios sin usar que siguen en la caja"], a: 0, why: "Deseche en recipientes rotulados/con código de color. Siga también las reglas estatales de desechos médicos." },
  { id: "wd-01", category: "welding", topic: "Subparte", q: "La soldadura y el corte en construcción son principalmente:", choices: ["1926 Subparte J", "1926 Subparte M", "1910.147", "1926 Subparte P"], a: 0, why: "1926.350–354. La soldadura en industria general es 1910.251–255." },
  { id: "wd-02", category: "welding", topic: "Gafas", q: "Los ayudantes y demás expuestos al arco necesitan:", choices: ["Ninguna protección ocular si a veces miran hacia otro lado", "Lentes de filtro o pantallas para no quedar expuestos al arco", "Solo cascos", "Vidrio claro"], a: 1, why: "El UV del arco causa “destello del soldador” (fotoqueratitis) también a los transeúntes. Use pantallas." },
  { id: "wd-03", category: "welding", topic: "Cilindros verticales", q: "Los cilindros de gas comprimido en uso deben:", choices: ["Acostarse para que no se caigan", "Asegurarse en vertical con protección de válvula salvo que estén diseñados de otro modo (el acetileno tiene límites especiales para acostarse)", "Almacenarse en la corriente de chispas", "Usarse como rodillos"], a: 1, why: "1926.350: asegure, tapas puestas cuando no se usan, acetileno no por encima de 15 psig." },
  { id: "wd-04", category: "welding", topic: "Presión de acetileno", q: "La presión de trabajo del acetileno no debe exceder:", choices: ["15 psig", "150 psig", "2,000 psig", "Siempre la presión del oxígeno"], a: 0, why: "El acetileno es inestable por encima de 15 psig en estado libre. Use el regulador correcto." },
  { id: "wd-05", category: "welding", topic: "Aceite y oxígeno", q: "El aceite o la grasa en las conexiones de oxígeno es:", choices: ["Un buen lubricante", "Peligroso: el oxígeno puede hacer que el aceite se inflame o explote", "Exigido por OSHA", "Solo un asunto de orden y limpieza"], a: 1, why: "Mantenga limpio el equipo de oxígeno. Nunca use aceite en reguladores ni roscas." },
  { id: "wd-06", category: "welding", topic: "Retroceso", q: "Los arrestadores de retroceso y las válvulas de retención de flujo inverso:", choices: ["Ayudan a impedir que el fuego viaje de vuelta a las mangueras y los cilindros", "Solo aumentan la velocidad de corte", "Reemplazan las tapas de los cilindros", "Son decorativos"], a: 0, why: "Prácticas del fabricante y OSHA/CGA. Inspeccione las mangueras por cortes y quemaduras." },
  { id: "wd-07", category: "welding", topic: "Permiso de trabajo en caliente", q: "Un sistema de permiso de trabajo en caliente se usa para:", choices: ["Controlar la soldadura/corte en áreas con combustibles: inspeccionar, proteger y asignar vigía de incendio", "Acelerar la producción saltándose el vigía de incendio", "Reemplazar los extintores", "Permitir soldar en atmósferas explosivas"], a: 0, why: "1910.252 / 1926.352: mueva combustibles, use resguardos, vigía de incendio." },
  { id: "wd-08", category: "welding", topic: "Soldadura en confinado", q: "Soldar en un espacio confinado requiere:", choices: ["Extracción local o aire suministrado según se necesite, prueba atmosférica y nunca usar oxígeno para ventilar", "Oxígeno puro para mantener estable el arco", "Ningún vigía", "Cilindros cerrados dentro del espacio como almacenamiento"], a: 0, why: "1926.353 / 1910.252(c): ventilación. Retire los cilindros de los espacios confinados cuando sea posible durante los descansos según se especifique." },
  { id: "wd-09", category: "welding", topic: "Recubrimientos", q: "Soldar sobre metal pintado o chapado puede liberar:", choices: ["Solo vapor", "Plomo, cadmio, zinc (fiebre de humos metálicos), isocianatos o cromatos según el recubrimiento", "Oxígeno puro", "Solo helio"], a: 1, why: "Quite los recubrimientos o use LEV/respiradores. Consulte la SDS del recubrimiento si puede." },
  { id: "wd-10", category: "welding", topic: "Humo de zinc", q: "La fiebre de humos metálicos se asocia comúnmente con:", choices: ["Soldar o cortar acero galvanizado (humo de óxido de zinc)", "Beber agua", "Solo polvo de madera", "Solo arena de sílice"], a: 0, why: "Síntomas tipo gripe horas después de la exposición. Ventile y evite comer en el penacho." },
  { id: "wd-11", category: "welding", topic: "Puesta a tierra", q: "La pinza de retorno (trabajo) de soldadura debe:", choices: ["Sujetarse a la pieza de trabajo o a un conductor de trabajo adecuado — no a través de acero del edificio, tuberías o cadenas como trayectoria casual si puede hacer arco e incendio", "Sujetarse a una tubería de rociadores contra incendio como mejor práctica", "Omitirse en soldadoras de CD", "Sujetarse por un ayudante con las manos desnudas"], a: 0, why: "La corriente de soldadura desviada inicia incendios y daña circuitos. Ponga la pinza cerca de la soldadura." },
  { id: "wd-12", category: "welding", topic: "Portaelectrodos", q: "Los portaelectrodos deben:", choices: ["Estar totalmente aislados y no sumergirse en agua para enfriar", "Dejarse en el suelo con un electrodo vivo", "Envolverse con cinta de ducto como aislamiento listado", "Sujetarse con la boca"], a: 0, why: "1926.351: aislamiento. No sumerja portaelectrodos calientes en agua." },
  { id: "wd-13", category: "welding", topic: "Cables", q: "Los cables de soldadura con aislamiento dañado:", choices: ["Deben repararse o reemplazarse; no ponga cinta como arreglo permanente en un conductor vivo a la ligera", "Están bien si se ve el cobre", "Funcionan mejor", "Deben enfriarse en aceite"], a: 0, why: "1926.351(b): no se usarán los cables que necesiten reparación." },
  { id: "wd-14", category: "welding", topic: "Pantallas", q: "Las pantallas de soldadura protegen a los demás de:", choices: ["Radiación del arco y chispas", "Solo ruido", "Solo sílice", "Derrumbes"], a: 0, why: "Coloque las pantallas de modo que no restrinjan la ventilación. Los acabados no reflectantes ayudan." },
  { id: "wd-15", category: "welding", topic: "Extintor en soldadura", q: "El equipo adecuado de extinción de incendios debe:", choices: ["Estar listo en el área de trabajo para trabajo en caliente", "Estar en otro edificio", "Ser opcional si tiene una botella de agua", "Ser solo Clase D"], a: 0, why: "1926.352(d): los extintores u otro equipo de combate de incendios estarán disponibles de inmediato." },
  { id: "wd-16", category: "welding", topic: "Tambores", q: "Soldar en tambores o tanques que contuvieron inflamables:", choices: ["Es seguro si “se ven vacíos”", "Requiere limpieza, inertización u otros procedimientos para que los vapores no exploten", "Es la mejor forma de abrirlos", "No necesita pruebas"], a: 1, why: "Los tambores vacíos explotan. Siga 1910.252(a)(3) / 1926.352(i) y las prácticas de la industria (purga, inertización)." },
  { id: "wd-17", category: "welding", topic: "EPP de soldadura", q: "Los soldadores suelen necesitar:", choices: ["Lente de filtro, ropa resistente a la flama, cuero o equivalente para chispas, y protección auditiva/respiratoria según lo exija la tarea", "Mangas cortas y sudaderas sintéticas", "Solo un tapabocas de papel", "Algodón empapado de solvente"], a: 0, why: "Los sintéticos se derriten. Cubra la piel del UV. Use el tono correcto." },
  { id: "wd-18", category: "welding", topic: "Tasa de ventilación", q: "Al soldar en un espacio con menos de 10,000 cf por soldador sin extracción local, las reglas de construcción de OSHA pueden exigir:", choices: ["Ventilación mecánica que cumpla el cfm especificado o protección respiratoria según aplique", "Ningún aire extra", "Enriquecimiento de oxígeno", "Cerrar todas las puertas"], a: 0, why: "1926.353: 2,000 cfm por soldador en algunos casos, o extracción local, o respiradores. Conozca el párrafo específico del proceso." },
  { id: "wd-19", category: "welding", topic: "Transporte de cilindros", q: "Al mover cilindros deben:", choices: ["Llevar tapa, estar asegurados y no izarse por la tapa salvo que esté diseñada como dispositivo de izaje (la mayoría no lo está)", "Rodarse en horizontal mientras están conectados al regulador", "Llevarse por la válvula", "Ir sueltos en la caja de un camión"], a: 0, why: "1926.350(a): tapas de protección de válvula en su lugar. Use un carrito." },
  { id: "wd-20", category: "welding", topic: "Arco vs gas", q: "Un peligro extra clave del SMAW/GMAW frente al oxicorte es:", choices: ["Choque eléctrico y radiación UV/IR del arco", "Ningún humo", "Ningún riesgo de incendio", "Ninguna necesidad de protección ocular"], a: 0, why: "Ambos tienen peligros de incendio y humo. El arco añade electricidad y radiación intensa." },
  { id: "st-01", category: "steel", topic: "Subparte R", q: "El montaje de acero está cubierto por:", choices: ["1926 Subparte R", "1910.147", "1926 Subparte P", "1910.1030"], a: 0, why: "1926.750–761: distribución del sitio, izaje, protección contra caídas y capacitación." },
  { id: "st-02", category: "steel", topic: "15 pies", q: "Salvo para conectores y cierto trabajo de entablado, la protección contra caídas en montaje de acero se exige en general a:", choices: ["6 pies", "15 pies", "30 pies", "solo a 25 pies"], a: 1, why: "1926.760(a): 15 pies. Los conectores tienen reglas adicionales entre 15 y 30 pies." },
  { id: "st-03", category: "steel", topic: "Conectores", q: "Un conector en el montaje de acero:", choices: ["Puede trabajar sin protección contra caídas entre 15 y 30 pies si está capacitado, ha completado el entablado/acceso y tiene PFAS disponible para uso inmediato según se especifique", "Nunca necesita protección contra caídas", "Debe usar barandales a 4 pies", "Está exento a todas las alturas"], a: 0, why: "1926.760(b): las disposiciones de conectores son específicas. A 30 pies deben estar protegidos." },
  { id: "st-04", category: "steel", topic: "Entablado controlado", q: "Una Zona de entablado controlado (CDZ) permite:", choices: ["Trabajo de entablado en borde de avance entre 15 y 30 pies con procedimientos específicos en lugar de PFAS convencional para esos trabajadores del borde", "Ninguna protección a 40 pies", "Que cualquiera camine el borde", "Omitir las fijaciones de la cubierta metálica"], a: 0, why: "1926.760(c): la CDZ está estrictamente limitada: empleados capacitados, ningún otro trabajo, máximo 90 pies de ancho, etc." },
  { id: "st-05", category: "steel", topic: "Conectores de cortante que tropiezan", q: "Los conectores de cortante que son un peligro de tropiezo en superficies de circulación:", choices: ["No se fijarán hasta después de instalar el entablado, según se especifique", "Deben instalarse primero siempre", "Reemplazan la protección contra caídas", "Solo se pintan para que se vean"], a: 0, why: "1926.754(c)(1): controle los peligros de tropiezo de conectores de cortante, barras de refuerzo, etc." },
  { id: "st-06", category: "steel", topic: "Aplomado", q: "El equipo de aplomado debe:", choices: ["Instalarse bajo la supervisión de una persona competente y dejarse en su lugar hasta que el acero esté asegurado", "Quitarse de inmediato después del primer perno", "Ser vientos opcionales de cualquier tamaño", "Atarse a la defensa de una camioneta"], a: 0, why: "1926.752 y .754: estabilidad. No quite riostras hasta que la estructura pueda sostenerse." },
  { id: "st-07", category: "steel", topic: "Dos pernos", q: "Antes de soltar un miembro de la línea de izaje, en general debe tener:", choices: ["Al menos dos pernos por conexión, apretados con llave, tensados, o el equivalente según se especifique", "Una sola soldadura de punteo", "Solo un pasador de deriva", "Nada: déjelo en el patín"], a: 0, why: "1926.756(a): dos pernos por conexión (o equivalente) antes de desenganchar, con excepciones en la norma para algunas uniones." },
  { id: "st-08", category: "steel", topic: "Anclaje de columna", q: "Las columnas deben:", choices: ["Anclarse con un mínimo de cuatro varillas/pernos de anclaje, entre otros requisitos", "Colocarse solo sobre cuñas de madera", "Quedar autoportantes sin anclajes a cualquier altura", "Soldarse al refuerzo en el lodo"], a: 0, why: "1926.755: cuatro varillas de anclaje, y una persona competente evalúa la adecuación. Se especifica la reparación de varillas dañadas." },
  { id: "st-09", category: "steel", topic: "Distribución del sitio", q: "Antes de que comience el montaje de acero, el contratista que controla debe proporcionar:", choices: ["Notificación escrita de que el concreto en pilas/muros/zapatas ha alcanzado la resistencia especificada (75% o según se especifique) e información de distribución/acceso del sitio", "Solo un apretón de manos", "Ninguna información", "Un mapa del sitio en blanco"], a: 0, why: "1926.752: deberes del contratista que controla. Los montadores necesitan caminos de acceso y áreas de acopio adecuados." },
  { id: "st-10", category: "steel", topic: "Izaje", q: "Durante el izaje de acero, los trabajadores no deben:", choices: ["Estar bajo la carga salvo los conectores necesarios para el proceso y que siguen la norma", "Usar líneas de guía cuando se necesiten", "Tener un aparejador calificado", "Usar un plan de izada para picos complejos"], a: 0, why: "1926.753: rutas, planificación previa y la prohibición de estar bajo cargas con una excepción para conectores." },
  { id: "st-11", category: "steel", topic: "Huecos en el entablado", q: "Los huecos en la cubierta metálica deben:", choices: ["Cubrir, resguardar o marcarse y protegerse para que las personas no pasen a través", "Dejarse abiertos para el cableado después", "Cubrir solo con una manta de aislamiento", "Ignorarse bajo 12 pulgadas"], a: 0, why: "1926.754(e) y las reglas de protección contra caídas. También las aberturas de tragaluces." },
  { id: "st-12", category: "steel", topic: "Capacitación de acero", q: "Los montadores de acero deben capacitar a los trabajadores sobre:", choices: ["Peligros de caída, aparejo de izada múltiple si se usa, y procedimientos de CDZ si se usa, entre otros temas", "Solo la nómina", "Solo primeros auxilios", "Nada si tienen OSHA 10"], a: 0, why: "1926.761: una persona calificada proporciona la capacitación. OSHA 10 es concientización, no certificación de la Subparte R." },
  { id: "st-13", category: "steel", topic: "Izada múltiple", q: "El aparejo de izada múltiple (árbol de Navidad) se permite solo cuando:", choices: ["Se usa un conjunto de aparejo de izada múltiple, los miembros son similares, cinco o menos, y se cumplen las demás condiciones de 1926.753(e)", "Necesita ir más rápido con ahorques de cualquier tipo", "Siempre está prohibido", "Solo con un montacargas"], a: 0, why: "Condiciones estrictas. Las grúas y el aparejo deben estar diseñados para ello." },
  { id: "st-14", category: "steel", topic: "Correas (purlins)", q: "Caminar sobre viguetas de acero o correas:", choices: ["Requiere que estén adecuadamente arriostradas/aseguradas; no camine sobre viguetas sin asegurar", "Siempre es seguro", "No necesita protección contra caídas a 20 pies", "Se prefiere a usar plataformas"], a: 0, why: "1926.757 y .754: arriostrado, arriostrado de montaje y protección contra caídas. Las viguetas sin asegurar ruedan." },
  { id: "st-15", category: "steel", topic: "Objetos que caen en acero", q: "Los artículos sueltos en altura deben:", choices: ["Asegurarse contra caídas; recipientes para pernos y pasadores de deriva", "Patearse del hierro hacia la cuadrilla en el suelo", "Dejarse en el patín", "Tirarse en una bolsa por el costado"], a: 0, why: "1926.759: protección contra objetos que caen. Rodapiés, redes o marquesinas según se exija; asegure las herramientas." },
  { id: "cn-01", category: "concrete", topic: "Subparte Q", q: "El concreto y la mampostería de construcción son principalmente:", choices: ["1926 Subparte Q", "1926 Subparte L", "1910.120", "1926 Subparte CC"], a: 0, why: "1926.700–706: colado en sitio, pretensado, losa izada, mampostería y zonas de acceso limitado." },
  { id: "cn-02", category: "concrete", topic: "Empalamiento", q: "El acero de refuerzo que sobresale debe:", choices: ["Resguardarse para evitar el empalamiento (tapas que cumplan la norma o canaletas, no tapas de hongo que fallan las pruebas)", "Dejarse filoso para que la gente lo note", "Pintarse solo de naranja", "Doblarse por aprendices como rito"], a: 0, why: "1926.701(b): proteja del empalamiento. Use dispositivos que realmente funcionen: OSHA ha citado tapas falsas de “hongo”." },
  { id: "cn-03", category: "concrete", topic: "Acceso limitado en mampostería", q: "Una zona de acceso limitado para muros de mampostería:", choices: ["Se establece en el lado sin andamio, igual a la altura más 4 pies, a lo largo del muro, restringida a albañiles, hasta que el muro esté apoyado", "Es siempre de 3 pies", "Es opcional para muros de más de 8 pies", "Reemplaza el arriostrado"], a: 0, why: "1926.706(a): LAZ. Los muros de más de 8 pies necesitan arriostrado hasta el apoyo permanente salvo que estén adecuadamente apoyados de otro modo." },
  { id: "cn-04", category: "concrete", topic: "Arriostrado de mampostería", q: "Un muro de mampostería de más de 8 pies de alto debe:", choices: ["Arriostrarse hasta que los elementos de apoyo permanentes estén en su lugar, salvo que pueda sostenerse sin arriostrado", "Dejarse autoportante al viento", "Sostenerse por los trabajadores", "Solo tener rodapié"], a: 0, why: "1926.706(b): evite el colapso. El viento y la mampostería verde son una mezcla mortal." },
  { id: "cn-05", category: "concrete", topic: "Cimbra", q: "La cimbra y el apuntalamiento deben:", choices: ["Diseñarse, erigirse, apoyarse, arriostrarse y mantenerse para que soporten todas las cargas", "Construirse de cualquier desperdicio", "Quitarse mientras el concreto sigue plástico siempre", "Treparse como escalera aunque no esté diseñado para ello"], a: 0, why: "1926.703: dibujos, inspecciones y reapuntalamiento. Las fallas causan múltiples fatalidades." },
  { id: "cn-06", category: "concrete", topic: "Dibujos", q: "Los dibujos y planos de cimbra deben:", choices: ["Estar disponibles en la obra", "Quedarse solo en la oficina del ingeniero", "Ser verbales", "Ser opcionales bajo 20 pies"], a: 0, why: "1926.703(a)(2): planos en el sitio. Una persona competente inspecciona antes, durante y después del colado según se especifique." },
  { id: "cn-07", category: "concrete", topic: "Prefabricado", q: "Los miembros prefabricados no deben usarse para almacenamiento ni tener cargas aplicadas hasta:", choices: ["Que puedan soportar la carga sin esfuerzo excesivo: siga al montador/ingeniero", "Que el camión se vaya", "Que seque la pintura", "Que OSHA visite"], a: 0, why: "1926.704: insertos de izaje, arriostrado y procedimientos de montaje. Nunca camine un muro que no esté arriostrado." },
  { id: "cn-08", category: "concrete", topic: "Tilt-up", q: "Durante el montaje tilt-up, los trabajadores no deben estar:", choices: ["Bajo el panel", "Usando líneas de guía desde un lugar seguro", "Siguiendo el plan de montaje", "Usando EPP"], a: 0, why: "1926.705: la losa izada tiene reglas extra. Los paneles tilt-up aplastan a las personas en la zona de caída." },
  { id: "cn-09", category: "concrete", topic: "Cubetas de concreto", q: "Viajar en una cubeta de concreto está:", choices: ["Prohibido", "Permitido si se agarra del cable", "Exigido para el colado", "Bien bajo 10 pies"], a: 0, why: "1926.701(d): no viajar en la cubeta. Mantenga a los trabajadores lejos del recorrido de la cubeta." },
  { id: "cn-10", category: "concrete", topic: "Manguera de bomba", q: "Las líneas de bomba de concreto pueden:", choices: ["Latigarse y golpear a los trabajadores; use sistemas, soportes y EPP adecuados; nunca mire dentro de una manguera tapada", "Sujetarse con la mano en el acople durante un reventón", "Usarse como columpio", "Omitir bloques y apuntalamiento"], a: 0, why: "Asegure la manguera, use reductores adecuados y trate las obstrucciones con procedimientos, no con la cara." },
  { id: "cn-11", category: "concrete", topic: "Sílice en concreto", q: "Cortar, esmerilar o taladrar concreto es una:", choices: ["Tarea que genera sílice: use métodos húmedos de la Tabla 1 o equivalente", "Tarea sin polvo", "Solo una tarea de ruido", "Siempre una tarea de plomo"], a: 0, why: "La Tabla 1 de 1926.1153 lista sierras, esmeriladoras y taladros. Agua o aspiradoras con cubierta." },
  { id: "cn-12", category: "concrete", topic: "Quemaduras de cemento", q: "El concreto húmedo y el cemento pueden causar:", choices: ["Quemaduras químicas cáusticas y dermatitis; use EPP y lávese", "Ningún efecto en la piel", "Solo polvo en los ojos, nunca en la piel", "Congelación"], a: 0, why: "Las quemaduras alcalinas pueden ser graves. Botas, guantes y lavaojos. No trabaje con ropa empapada." },
  { id: "cn-13", category: "concrete", topic: "Andamio de mampostería", q: "El trabajo de mampostería en voladizo en andamios igual necesita:", choices: ["Protección contra caídas según la Subparte L y protección contra objetos que caen para las personas abajo", "Ningún barandal porque los albañiles necesitan alcanzar", "Solo una LAZ en el andamio", "Cinturones de cuerpo"], a: 0, why: "No quite barandales para asentar ladrillo sin otro sistema. Existen plataformas voladizas y sistemas debidamente diseñados." },
  { id: "cn-14", category: "concrete", topic: "Postensado", q: "Durante el postensado, los trabajadores no deben estar:", choices: ["Detrás del gato (el tendón puede dispararse): manténgase fuera de la línea de fuego", "Siguiendo el procedimiento de tensado", "Usando equipo calibrado", "Usando protección ocular"], a: 0, why: "1926.701(c): ningún empleado bajo el tendón durante el tensado salvo los requeridos. El lado de la cuña es un peligro de misil." },
  { id: "cn-15", category: "concrete", topic: "Bloqueo en concreto", q: "Antes de meter la mano en una revolvedora de concreto o la tolva de una bomba:", choices: ["Bloquee y etiquete el equipo", "Solo grite “espérate”", "Meta la mano mientras está en marcha intermitente", "Use un palo mientras corre"], a: 0, why: "Peligro de atrapamiento. Aísle la energía. Las revolvedoras matan." },
  { id: "rp-01", category: "respiratory", topic: "Norma", q: "La Norma de protección respiratoria es:", choices: ["1910.134 (aplicada a la construcción mediante 1926.103)", "1926.501", "1910.178", "1904.7"], a: 0, why: "Programa escrito, médico, prueba de ajuste, capacitación y calendarios de cambio de cartuchos." },
  { id: "rp-02", category: "respiratory", topic: "Programa escrito", q: "Se exige un programa respiratorio escrito cuando:", choices: ["Los respiradores son necesarios para proteger la salud o los exige el empleador", "Solo si tiene 100 empleados", "Nunca para N95", "Solo en minería"], a: 0, why: "1910.134(c): administrador del programa, procedimientos y detalles específicos del sitio. El uso voluntario tiene un conjunto menor de deberes (Apéndice D)." },
  { id: "rp-03", category: "respiratory", topic: "N95 voluntario", q: "Si el empleador permite el uso voluntario de una pieza facial filtrante (tapabocas de polvo) donde no se exige respirador:", choices: ["Proporcione la información del Apéndice D; no se exige un programa completo para el tapabocas mismo (el médico igual aplica al uso voluntario elastomérico)", "No haga nada", "Haga prueba de ajuste mensual", "Entregue SCBA"], a: 0, why: "1910.134(c)(2): distinga pieza facial filtrante vs uso voluntario elastomérico. El uso voluntario elastomérico igual necesita evaluación médica y limpieza." },
  { id: "rp-04", category: "respiratory", topic: "Médico PLHCP", q: "La evaluación médica la hace:", choices: ["Un médico u otro profesional de la salud con licencia (PLHCP), usando el cuestionario o un examen", "El capataz", "Un compañero que “se ve saludable”", "OSHA en línea"], a: 0, why: "1910.134(e): examen de seguimiento si el cuestionario lo indica. El empleador paga y es confidencial." },
  { id: "rp-05", category: "respiratory", topic: "Tipos de prueba de ajuste", q: "Las pruebas de ajuste cualitativas incluyen:", choices: ["Sacarina, Bitrex, acetato de isoamilo (aceite de plátano) y humo irritante (con límites)", "Solo PortaCount", "Solo una revisión en el espejo", "Aguantar la respiración"], a: 0, why: "QLFT es pasa/falla por sabor/olor/irritación. QNFT mide la fuga numéricamente. QLFT en general solo para APF 10." },
  { id: "rp-06", category: "respiratory", topic: "Revisión de sello del usuario", q: "Una revisión de sello del usuario se realiza:", choices: ["Cada vez que se pone el respirador", "Una vez al año", "Solo en la oficina", "Nunca con N95"], a: 0, why: "1910.134(f)(1)(ii) y Apéndice B-1: revisiones de presión positiva y/o negativa. No sustituye la prueba de ajuste anual." },
  { id: "rp-07", category: "respiratory", topic: "Calendario de cambio", q: "Para cartuchos de gas/vapor, el empleador debe:", choices: ["Usar un calendario de fin de vida útil basado en datos, o un ESLI si es confiable, no solo “cuando lo huelo” como plan principal para muchos químicos", "Cambiarlos cada 5 años", "Nunca cambiarlos", "Depender siempre solo del olor"], a: 0, why: "1910.134(d)(3)(iii): las propiedades de advertencia no bastan para muchos químicos (incluido el CO, que no tiene ninguna)." },
  { id: "rp-08", category: "respiratory", topic: "Significado de N95", q: "N95 significa que el filtro:", choices: ["No es resistente al aceite y filtra al menos el 95% del aerosol de prueba", "Detiene el 95% de los gases", "Sirve para IDLH", "Suministra oxígeno"], a: 0, why: "N = no aceite, R = resistente, P = a prueba de aceite. 95/99/100 son eficiencias. Los filtros no añaden oxígeno ni detienen muchos vapores." },
  { id: "rp-09", category: "respiratory", topic: "Deficiencia de oxígeno", q: "Los respiradores purificadores de aire no deben usarse en:", choices: ["Atmósferas con deficiencia de oxígeno (en general bajo 19.5%) o IDLH salvo que el respirador esté diseñado para ello (SCBA/SAR)", "Polvo molesto bajo el PEL con uso voluntario", "Polen al aire libre", "Humos de pintura si el cartucho está clasificado y el oxígeno es normal, como parte de un programa"], a: 0, why: "Los APR necesitan oxígeno. También necesitan el cartucho correcto y una concentración bajo IDLH y bajo la concentración máxima de uso." },
  { id: "rp-10", category: "respiratory", topic: "MUC", q: "La concentración máxima de uso es aproximadamente:", choices: ["APF por el PEL (con IDLH como tope)", "Siempre 100 veces cualquier PEL", "El umbral de olor", "Cero"], a: 0, why: "MUC = APF × límite de exposición ocupacional, sin exceder IDLH. Cara completa APF 50 × PEL, etc." },
  { id: "rp-11", category: "respiratory", topic: "Almacenamiento", q: "Los respiradores deben almacenarse:", choices: ["Para protegerlos de daño, polvo, sol, calor y deformación — no colgando de un clavo bajo la lluvia", "En el totes del químico", "Dentro de una cabina de esmerilado sin protección", "Bajo el asiento del camión mezclados con aceite"], a: 0, why: "1910.134(h): limpie, inspeccione y almacene. Las piezas faciales aplastadas tendrán fugas." },
  { id: "rp-12", category: "respiratory", topic: "SCBA", q: "El SCBA para entrada IDLH requiere:", choices: ["Demanda de presión u otra presión positiva, mínimo de 30 minutos clasificados en general, y una persona de reserva con equipo de rescate", "Un tapabocas de polvo y un compañero lejos", "Demanda de presión negativa", "Ninguna capacitación"], a: 0, why: "1910.134(g)(3) y (d)(2). El combate interior de incendios tiene superposición con NFPA." },
  { id: "rp-13", category: "respiratory", topic: "Barbas", q: "Los respiradores de ajuste hermético y las barbas:", choices: ["Son incompatibles si el vello rompe el sello", "Están bien con correas extra", "Se exigen juntos", "Solo importan para SCBA"], a: 0, why: "1910.134(g)(1)(i): nada de vello en la superficie de sello. Ofrezca un PAPR con capucha holgada si el programa lo permite y el APF basta." },
  { id: "rp-14", category: "respiratory", topic: "Lentes", q: "Los kits de lentes para respiradores de cara completa:", choices: ["Permiten lentes de receta sin romper el sello: no use lentes de calle bajo una cara completa de un modo que tenga fugas", "Están prohibidos", "Reemplazan la necesidad de prueba de ajuste", "Son solo para soldadura"], a: 0, why: "Las patillas rompen el sello. Use insertos diseñados para la pieza facial." },
  { id: "rp-15", category: "respiratory", topic: "Capacitación respiratoria", q: "La capacitación de respiradores se exige:", choices: ["Al inicio y al menos anualmente, y cuando sea necesario por cambios o conocimiento inadecuado", "Una vez", "Solo para el administrador del programa", "Nunca si se entregó el Apéndice D para uso requerido"], a: 0, why: "1910.134(k): demuestre cómo inspeccionar, ponerse, hacer una revisión de sello y conocer las limitaciones." },
  { id: "mg-01", category: "machineguard", topic: "Norma", q: "El resguardo de maquinaria en industria general es principalmente:", choices: ["1910.212 (general) más reglas específicas de máquina (sierras, fresadoras, etc.)", "1926.501", "1910.1200", "solo 1904"], a: 0, why: "El punto de operación, los puntos de pellizco de entrada, las partes rotatorias y las virutas que vuelan deben resguardarse." },
  { id: "mg-02", category: "machineguard", topic: "Punto de operación", q: "El punto de operación es:", choices: ["Donde el trabajo se realiza realmente sobre el material (cortar, dar forma, barrenar)", "El botón de arranque", "El comedor", "Solo el motor"], a: 0, why: "1910.212(a)(3): resguarde el punto de operación si expone a los operadores a lesión." },
  { id: "mg-03", category: "machineguard", topic: "Álabes de ventilador", q: "Cuando la periferia de los álabes del ventilador está a menos de 7 pies sobre el piso o el nivel de trabajo, los álabes deben:", choices: ["Resguardarse con aberturas no mayores de 1/2 pulgada", "Quedar sin resguardo para el flujo de aire", "Pintarse solo de amarillo", "Quitarse"], a: 0, why: "1910.212(a)(5): aberturas máximas de 1/2 pulgada en los resguardos de ventilador." },
  { id: "mg-04", category: "machineguard", topic: "Anclaje", q: "Las máquinas diseñadas para una ubicación fija deben:", choices: ["Anclarse para evitar que caminen o se muevan", "Estar sobre ruedas sin trabas siempre", "Sujetarse por el operador", "Colocarse sobre cartón"], a: 0, why: "1910.212(b): anclaje. Las taladradoras de columna y las esmeriladoras “caminan” y causan lesión." },
  { id: "mg-05", category: "machineguard", topic: "Sierra de mesa", q: "Una sierra de mesa debe tener:", choices: ["Un resguardo de hoja, cuchillo divisor/separador y dispositivos antikickback según el diseño; nunca quítelos para cortes pasantes", "Ningún resguardo para poder ver", "Un juego de dado sin ninguna protección nunca", "La guía solo a la izquierda como regla"], a: 0, why: "1910.213: trabajo en madera. El kickback mata. Use palos empujadores y mantenga los resguardos puestos." },
  { id: "mg-06", category: "machineguard", topic: "Prensa mecánica", q: "Las prensas mecánicas de potencia tienen:", choices: ["Reglas detalladas 1910.217 que incluyen detección de presencia, retenedores, controles de dos manos y bloqueo para el cambio de troqueles", "Ninguna norma", "Solo un letrero", "Resguardos que pueden atarse hacia atrás de forma permanente"], a: 0, why: "Las amputaciones son comunes. La iniciación por dispositivo de detección de presencia tiene requisitos extra. Nunca anule las cortinas de luz." },
  { id: "mg-07", category: "machineguard", topic: "LOTO vs resguardos", q: "Los resguardos de máquina protegen durante:", choices: ["La producción normal; el LOTO protege durante el servicio cuando se quitan o anulan los resguardos", "Solo el servicio", "Ninguno de los dos", "Solo el trabajo eléctrico"], a: 0, why: "Si mete la mano alrededor de un resguardo o lo quita, necesita 1910.147 (o la excepción de servicio menor si realmente aplica)." },
  { id: "mg-08", category: "machineguard", topic: "Interbloqueos", q: "Los interbloqueos de resguardo deben:", choices: ["Detener el movimiento peligroso cuando se abre el resguardo; no deben ser fáciles de anular", "Cubrirlos con cinta para correr más rápido", "Ser opcionales", "Solo encender un LED"], a: 0, why: "Anular interbloqueos es una causa principal de amputación. ANSI B11 y OSHA se preocupan por ello." },
  { id: "mg-09", category: "machineguard", topic: "Puntos de pellizco", q: "Los puntos de pellizco de entrada ocurren en:", choices: ["Cilindros rotatorios, bandas y poleas, y engranes que engranan", "Mesas planas sin movimiento", "Escaleras", "Cascos"], a: 0, why: "El cabello, la ropa y los dedos se meten. Resguarde o ubique a una distancia segura." },
  { id: "mg-10", category: "machineguard", topic: "PTO", q: "Los ejes de toma de fuerza en el equipo deben:", choices: ["Resguardarse", "Usarse como peldaño", "Dejarse descubiertos solo en granjas para que OSHA nunca aplique (las granjas pueden tener reglas/excepciones, pero los PTO de industria necesitan resguardos)", "Solo pintarse"], a: 0, why: "1910.219 maquinaria y equipo de construcción: los ejes rotatorios agarran la ropa en un segundo." },
  { id: "mg-11", category: "machineguard", topic: "Herramientas de mano", q: "Usar una herramienta de mano para alimentar una máquina:", choices: ["Puede mantener las manos fuera del punto de operación cuando se diseña así", "Significa que los resguardos siempre pueden quitarse", "Está prohibido", "Reemplaza el bloqueo para reparaciones dentro de la máquina"], a: 0, why: "Los palos empujadores, las pinzas y los accesorios son métodos de trabajo. No reemplazan los resguardos exigidos." },
  { id: "mg-12", category: "machineguard", topic: "Herramientas de construcción", q: "Las herramientas eléctricas de construcción deben tener:", choices: ["Resguardos mantenidos en su lugar (1926.300)", "Resguardos quitados siempre para trabajo de concreto", "Ningún cordón", "Carcasas de metal en todas las herramientas de doble aislamiento"], a: 0, why: "Sierras circulares, ruedas abrasivas y esmeriladoras: resguardos puestos. Las sierras recíprocas igual necesitan control de la hoja." },
  { id: "mg-13", category: "machineguard", topic: "Paro de emergencia", q: "Los paros de emergencia deben:", choices: ["Ser accesibles, estar claramente marcados y no usarse como el paro normal si el diseño exige un desconectador aparte para LOTO", "Ocultarse detrás de la máquina", "Ser el único dispositivo de bloqueo", "Atarse en la posición de encendido"], a: 0, why: "Los E-stop son para emergencias. El aislamiento para servicio igual necesita un desconectador que se pueda bloquear." },
  { id: "mg-14", category: "machineguard", topic: "Virutas", q: "Las máquinas que crean virutas que vuelan necesitan:", choices: ["Resguardos, pantallas o EPP (y generalmente ambos)", "Solo protección auditiva", "Ninguna protección ocular si entrecierra los ojos", "Un ventilador para soplar virutas a los demás"], a: 0, why: "1910.212(a)(1): virutas y chispas que vuelan. Los tornos necesitan resguardos de viruta." },
  { id: "mg-15", category: "machineguard", topic: "Capacitación de máquinas", q: "Los operadores deben capacitarse sobre:", choices: ["Peligros, resguardos y no quitar ni anular la protección", "Solo cuotas de producción", "Cómo anular las cortinas de luz", "Nada si la máquina es vieja"], a: 0, why: "1910.212 más normas específicas. Los supervisores deben hacer cumplir una cultura de resguardos puestos." },
  { id: "ae-01", category: "aerial", topic: "MEWP", q: "Las plataformas elevadoras móviles de trabajo (plataformas aéreas, de tijera, de brazo) en construcción se abordan en:", choices: ["1926.453 e instrucciones del fabricante; ANSI/SAIA A92 es el consenso de la industria", "solo 1926.652", "1910.1030", "solo Subparte P"], a: 0, why: "1926.453 se basa en el ANSI A92.2 más antiguo. Siga el manual: protección contra caídas, pendiente y límites de viento." },
  { id: "ae-02", category: "aerial", topic: "Arnés en brazo", q: "En una plataforma aérea apoyada en brazo, los ocupantes en general deben:", choices: ["Usar un sistema personal de detención de caídas o de restricción de recorrido sujeto al brazo o la canastilla según especifique el fabricante", "Pararse en el barandal intermedio", "Trepar el brazo", "Usar un cinturón de cuerpo para detención"], a: 0, why: "1926.453(b)(2)(v): cinturón de cuerpo con eslinga sujeta al brazo o la canastilla: la práctica moderna es un arnés de cuerpo completo. No se amarre a una estructura adyacente." },
  { id: "ae-03", category: "aerial", topic: "PFAS en tijera", q: "En plataformas de tijera, la protección contra caídas es principalmente:", choices: ["El sistema de barandal; el PFAS se usa si el fabricante lo exige o si los barandales no son equivalentes", "Siempre una eslinga de 6 pies al piso de abajo", "Nunca se necesita", "Solo una línea de advertencia en el suelo"], a: 0, why: "No trepe los barandales. Si abre una puerta o se para en los rieles, ha creado un peligro de caída: use restricción/detención según se exija." },
  { id: "ae-04", category: "aerial", topic: "Amarre a estructura", q: "Amarar la eslinga de una plataforma aérea a un edificio o poste adyacente:", choices: ["Puede sacarlo de la canastilla si la plataforma se mueve: en general está prohibido", "Es el anclaje preferido", "Aumenta la capacidad", "Reemplaza los estabilizadores"], a: 0, why: "Ancle al punto designado en la plataforma. Salir catapultado de la canastilla es un patrón conocido de fatalidad." },
  { id: "ae-05", category: "aerial", topic: "Capacidad de peso", q: "La capacidad de la plataforma incluye:", choices: ["Trabajadores, herramientas y materiales: no exceda la carga nominal", "Solo personas, las herramientas son gratis", "Solo la carga de viento", "Ilimitada si se mueve despacio"], a: 0, why: "Lea la tabla de capacidad a distintos alcances (plataformas de brazo). El hielo y el agua añaden peso." },
  { id: "ae-06", category: "aerial", topic: "Condiciones del suelo", q: "Operar en una pendiente o suelo suave:", choices: ["Puede causar volcadura; use estabilizadores/extienda ejes según se exija y quédese dentro de los límites de pendiente", "Está bien a altura completa", "Solo importa para plataformas de tijera", "Se resuelve conduciendo más rápido"], a: 0, why: "Los indicadores de nivel existen por una razón. El apuntalamiento debe ser adecuado. Vigile las bóvedas subterráneas." },
  { id: "ae-07", category: "aerial", topic: "Líneas eléctricas aéreas", q: "Las plataformas aéreas cerca de líneas aéreas necesitan:", choices: ["Las mismas distancias de aproximación eléctrica que otro equipo: 10 pies o más, o desenergizar", "Ninguna distancia si la canastilla es de fibra de vidrio", "Siempre 3 pies", "Contacto para probar si la línea está viva"], a: 0, why: "1926.453(b)(2)(ix) y 1926.1408 / .416. Los brazos aislados son para trabajo calificado de despeje de líneas, no un pase libre para peones de construcción." },
  { id: "ae-08", category: "aerial", topic: "Desniveles", q: "Las plataformas de tijera cerca de muelles de carga o zanjas:", choices: ["Pueden salirse del borde; use barricadas y vigías", "Son demasiado pesadas para caer", "Deben conducirse con la plataforma totalmente elevada para visibilidad", "No necesitan inspección del piso"], a: 0, why: "Conduzca bajada. Inspeccione las losas por huecos. Los muelles necesitan protección del borde." },
  { id: "ae-09", category: "aerial", topic: "Viento", q: "Las clasificaciones de viento del fabricante:", choices: ["Deben seguirse; baje la plataforma o detenga el trabajo con viento fuerte", "Son opcionales", "Solo aplican a grúas", "Aumentan a medida que sube"], a: 0, why: "El área de vela de letreros, revestimiento y la plataforma atrapan el viento. Las volcaduras ocurren con ráfagas." },
  { id: "ae-10", category: "aerial", topic: "Capacitación aérea", q: "Los operadores deben:", choices: ["Capacitarse en el modelo que usan, incluidas las clasificaciones interior vs exterior y el descenso de emergencia", "Autodidactas el primer día sin supervisión", "Recibir solo las llaves", "Certificarse por OSHA en persona"], a: 0, why: "1926.453(b)(2)(ii) y ANSI A92: capacitación y familiarización. Plan de rescate si el operador queda incapacitado." },
  { id: "ae-11", category: "aerial", topic: "Ambos pies", q: "Trabaje desde la plataforma con:", choices: ["Ambos pies en el piso; no trepe barandales ni use escaleras en la canastilla", "Un pie en el barandal intermedio para ganar altura", "Un tambor de 55 galones como peldaño", "Parado en el rodapié"], a: 0, why: "1926.453(b)(2)(iv): siempre párese firmemente en el piso de la canastilla. No se siente ni trepe el borde." },
  { id: "ae-12", category: "aerial", topic: "Frenos y estabilizadores", q: "Antes de elevar la plataforma:", choices: ["Ponga los frenos y los estabilizadores/estabilizadores según se exija; en algunas tijeras, la extensión retráctil totalmente adentro", "Deje el camión en marcha rodando", "Eleve primero y luego nivele", "Desconecte el paro de emergencia"], a: 0, why: "La inspección previa al uso incluye funciones, controles, fugas y calcomanías. No opere con una falla activa." },
  { id: "ae-13", category: "aerial", topic: "Circular elevado", q: "Circular con una plataforma de brazo elevada:", choices: ["Solo si el fabricante permite circulación plegada/a velocidad limitada; muchas exigen el brazo plegado", "Siempre a altura completa por la carretera", "Nunca con el brazo sobre la cabina como regla para todos los modelos", "Es más rápido que plegar así que se exige"], a: 0, why: "Siga el manual. Las obras tienen eventos de golpes y volcadura cuando la gente “conduce aérea”." },
  { id: "ae-14", category: "aerial", topic: "Electrocución y fibra de vidrio", q: "Un brazo de fibra de vidrio:", choices: ["Puede estar aislado para un kV especificado si está probado y limpio: la suciedad y la humedad reducen el aislamiento; no protege a ocupantes que contactan un segundo punto", "Hace seguro todo el trabajo eléctrico para cualquiera", "Significa que puede tocar líneas primarias de distribución", "No necesita inspección"], a: 0, why: "Solo las cuadrillas calificadas de despeje de líneas usan dispositivos aéreos aislados según el diseño. Los trabajadores de construcción se mantienen lejos de las líneas." },
  { id: "ae-15", category: "aerial", topic: "Rescate aéreo", q: "Si un trabajador queda atorado en altura o después de una caída en el arnés:", choices: ["Tenga un plan de rescate (controles de tierra, una segunda máquina o rescate capacitado): no lo deje suspendido", "Espere a que baje trepando el brazo", "Llame solo a la empresa de renta la semana siguiente", "Sacuda la plataforma"], a: 0, why: "Controles de tierra y descenso de emergencia: capacite a una persona en tierra. El trauma por suspensión es crítico en el tiempo." }
];
